92	    await api.closeIssue(gh, repo, item.number, spec.stateReason);
93	    // §15.19: whoever closes an item releases what it was holding.
94	    const freed = await readyDependents(api, gh, repo, item.number, { now, log });
95	    return { ok: true, closed: true, freed };
96	  }
97	  // Every park wears BOTH labels: `needs-human` is the state every guard and
98	  // sweep reads, the sub-label is what the person is being asked for.
99	  await api.swapLabel(gh, repo, item.number, AGENT, NEEDS_HUMAN);
100	  await api.addLabel(gh, repo, item.number, spec.label);
101	  // A REQUEST ITEM WRITES BACK TO ITS ISSUE, on the one end that is its business
102	  // (§16.5). Only the approval park: a failure deliberately writes nothing and
103	  // leaves `claude-queued` standing, because re-arming work that writes code is a
104	  // person's decision and that standing label is what stops the next tick queueing
105	  // a second run of the same request.
106	  const { request } = parseWorkItemBody(item.body ?? '');
107	  if (request && plan.outcome === 'approval') {
108	    await api.comment(gh, repo, request,
109	      `A pull request for this is open and waiting on you: #${plan.pr}. Merge or close it.`);
110	    await api.swapLabel(gh, repo, request, QUEUED_LABEL, IN_REVIEW_LABEL);
111	  }
112	  return { ok: true, closed: false, freed: [], request: request ?? null };
113	}
114	
115	async function main() {
116	  const plan = parseArgs(process.argv.slice(2));
117	  if (plan.error) {
118	    console.error(`converge-item: ${plan.error}`);
119	    process.exit(2);
120	  }
121	  const { makeGh, actionRepoContext } = await import('../signals/gh.mjs');
122	  const api = await import('../github.mjs');
123	  const { repo } = actionRepoContext();
124	  if (!repo) { console.error('converge-item: GITHUB_REPOSITORY is not set'); process.exit(1); }
125	
126	  const res = await convergeItem(api, makeGh(), repo, plan);
127	  if (!res.ok) { console.error(`converge-item: ${res.error}`); process.exit(1); }
128	  console.log(res.closed
129	    ? `converged #${plan.issue}: closed ${OUTCOMES[plan.outcome].label}`
130	      + (res.freed.length ? `, released ${res.freed.map((n) => `#${n}`).join(', ')}` : '')
131	    : `converged #${plan.issue}: parked ${OUTCOMES[plan.outcome].label}, left open for a person`);
132	}
133	
134	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
135	  main().catch((e) => { console.error(e); process.exit(1); });
